function startWorkerRealtime() { window.RozgaarRealtime?.start({ apiBase: API_BASE, token: state.token, user: state.user, onEvent: () => loadCore(), onStatus: status => document.body.dataset.realtimeStatus = status }); }

const API_BASE = localStorage.getItem('rozgaar_api_base') || 'http://127.0.0.1:8000/api/v1';
const state = { token: localStorage.getItem('rozgaar_worker_token') || localStorage.getItem('rozgaar_token'), user: null, jobs: [], applications: [], schedule: [], availability: [], payments: [], notifications: [], reviews: [], complaints: [], view: 'home', eventsBound: false };
let workerMap = null;
let workerMapLayers = [];
const $ = (selector, parent = document) => parent.querySelector(selector);
const $$ = (selector, parent = document) => [...parent.querySelectorAll(selector)];
const esc = value => String(value ?? '').replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' }[char]));
const money = value => value === undefined || value === null ? '—' : `₹${Number(value).toLocaleString('en-IN')}`;
const dateLabel = value => value ? new Intl.DateTimeFormat('en-IN', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(value)) : 'Flexible date';
const timeLabel = value => value ? value.slice(0, 5) : '';
const label = value => String(value || 'PENDING').replaceAll('_', ' ');

async function api(path, options = {}) {
  const headers = { ...(options.body instanceof FormData ? {} : { 'Content-Type': 'application/json' }), ...(options.headers || {}) };
  if (state.token) headers.Authorization = `Bearer ${state.token}`;
  const response = await fetch(`${API_BASE}${path}`, { ...options, headers });
  if (response.status === 204) return null;
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body?.error?.detail || body?.detail || 'Something went wrong.');
  if (path === '/auth/me' && body?.id && state.token) { state.user = body; startWorkerRealtime(); }
  return body;
}

function shell() {
  document.body.innerHTML = `<div class="app"><div class="shell"><header class="topbar"><a class="brand" href="#home" data-view="home" aria-label="Rozgaar worker home"><span class="brand-mark">r</span><span>rozgaar / worker</span></a><nav class="nav" aria-label="Worker navigation">${[['home','Home'],['discover','Find work'],['applications','Applications'],['schedule','Schedule'],['earnings','Earnings'],['history','Work history'],['profile','Profile'],['support','Support']].map(([key, text]) => `<button data-view="${key}">${text}</button>`).join('')}</nav><div class="user-area" id="user-area"></div></header></div><main id="main"></main><div class="drawer-backdrop" data-action="close-drawer"></div><aside class="drawer" id="drawer" aria-hidden="true"></aside><div class="toast" role="status" aria-live="polite"></div></div>`;
  bindEvents(); updateUserArea(); state.token ? loadCore() : renderLogin();
}

function bindEvents() { if (state.eventsBound) return; state.eventsBound = true; document.addEventListener('click', event => { const view = event.target.closest('[data-view]')?.dataset.view; const action = event.target.closest('[data-action]')?.dataset.action; if (view) navigate(view); if (action === 'close-drawer') closeDrawer(); if (action === 'open-login') openLoginDrawer(); if (action === 'open-register') openRegisterDrawer(); if (action === 'how-it-works') openHowItWorks(); if (action === 'logout') logout(); if (action === 'refresh') loadCore(); if (action === 'open-job') openJob(event.target.closest('[data-action="open-job"]').dataset.id); if (action === 'apply') openApply(event.target.closest('[data-action="apply"]').dataset.id); if (action === 'counter') openCounter(event.target.closest('[data-action="counter"]').dataset.id); if (action === 'withdraw') withdraw(event.target.closest('[data-action="withdraw"]').dataset.id); if (action === 'notification') markNotification(event.target.closest('[data-action="notification"]').dataset.id); if (action === 'mark-all') markAllRead(); if (action === 'retry') loadCore(); if (action === 'open-availability') openAvailability(); if (action === 'delete-availability') deleteAvailability(event.target.closest('[data-action="delete-availability"]').dataset.id); if (action === 'worker-completion') submitWorkerCompletion(event.target.closest('[data-action]').dataset.job); if (action === 'complaint') openComplaint(event.target.closest('[data-action="complaint"]').dataset.job); }); }
function updateUserArea() { const slot = $('#user-area'); if (!slot) return; slot.innerHTML = state.user ? `<span class="user-name"><span class="avatar">${esc(state.user.name?.[0] || 'W')}</span>${esc(state.user.name.split(' ')[0])}</span><button class="button secondary small" data-action="logout">Log out</button>` : '<div style="display:flex; gap:8px; flex-wrap:wrap"><button class="button secondary small" data-action="open-login">Log in</button><button class="button primary small" data-action="open-register">Sign up</button></div>'; }
function navigate(view) { if (!state.token) return view === 'home' ? renderLogin() : openLoginDrawer(); state.view = view; updateNavigation(); renderView(); window.scrollTo({ top: 0, behavior: 'smooth' }); }
function updateNavigation() { $$('.nav button').forEach(button => button.classList.toggle('active', button.dataset.view === state.view)); }

async function loadCore() { renderLoading(); try { const [user, jobs, applications, schedule, availability, payments, notifications, reviews, complaints] = await Promise.all([api('/auth/me'), api('/jobs?status=POSTED&page=1&page_size=50'), api('/applications/my'), api('/workers/me/upcoming-jobs'), api('/workers/me/availability'), api('/workers/me/payments'), api('/notifications?page=1&page_size=15'), api('/reviews/my'), api('/complaints/my')]); state.user = user; state.jobs = jobs?.items || []; state.applications = applications || []; state.schedule = schedule || []; state.availability = availability || []; state.payments = payments?.items || []; state.notifications = notifications?.items || []; state.reviews = reviews?.items || []; state.complaints = complaints?.items || []; updateUserArea(); updateNavigation(); renderView(); } catch (error) { if (/credentials|authentication/i.test(error.message)) { state.token = null; localStorage.removeItem('rozgaar_worker_token'); localStorage.removeItem('rozgaar_token'); updateUserArea(); renderLogin(); showToast('Your session expired. Please sign in again.'); } else renderError(error.message); } }
function renderLoading() { $('#main').innerHTML = `<section class="page"><div class="shell"><div class="loading"><span class="spinner"></span>Loading your worker workspace…</div></div></section>`; }
function renderError(message) { $('#main').innerHTML = `<section class="page"><div class="shell"><div class="error-state"><strong>We couldn’t load your workspace.</strong><span>${esc(message)}</span><div style="margin-top:14px"><button class="button primary small" data-action="retry">Try again</button></div></div></div></section>`; }

function renderView() { if (state.view === 'home') return renderHome(); if (state.view === 'discover') return renderDiscover(); if (state.view === 'applications') return renderApplications(); if (state.view === 'schedule') return renderSchedule(); if (state.view === 'earnings') return renderEarnings(); if (state.view === 'history') return renderHistory(); if (state.view === 'profile') return renderProfile(); renderSupport(); }
function pageHeader(eyebrow, title, copy, action = '') { return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h2>${title}</h2><p>${copy}</p></div>${action}</div>`; }
function renderHome() { const next = state.schedule[0]; const unread = state.notifications.filter(item => !item.is_read).length; const total = state.payments.reduce((sum, item) => sum + (item.status === 'COMPLETED' ? Number(item.advance_amount || 0) + Number(item.final_amount || 0) : 0), 0); $('#main').innerHTML = `<section class="hero"><div class="shell"><div class="hero"><div><p class="eyebrow">Your working day, in view</p><h1>Good work is easier to find when the details are clear.</h1><p class="hero-copy">Discover nearby opportunities, make a fair proposal, and keep your schedule and earnings in one steady place.</p><div class="actions"><button class="button primary" data-view="discover">Find work <span aria-hidden="true">→</span></button><button class="button secondary" data-view="schedule">Open schedule</button></div></div><div class="hero-board"><div class="kicker">Worker signal</div><div class="signal"><div><span class="signal-label">Next on your schedule</span><strong>${next ? esc(next.job_title) : 'Your next opportunity'}</strong></div><span class="signal-mark">↗</span></div><div class="signal"><div><span class="signal-label">Completed work</span><strong>${state.reviews.length || 0} reviewed jobs</strong></div><span class="signal-mark">✦</span></div><div class="signal"><div><span class="signal-label">Recorded earnings</span><strong>${money(total)}</strong></div><span class="signal-mark">₹</span></div></div></div></div></section><section class="page"><div class="shell"><div class="page-heading"><div><p class="eyebrow">Worker command center</p><h2>Know your next move.</h2><p>Opportunities, commitments, and money earned from the work you do.</p></div><button class="button secondary small" data-action="refresh">Refresh ↻</button></div>${overview()}<div class="board"><section class="panel"><div class="panel-head"><div><div class="kicker">Next job</div><h3>${next ? 'Ready when you are.' : 'Your next opportunity is ahead.'}</h3></div><button class="text-button" data-view="schedule">Full schedule →</button></div>${next ? nextJob(next) : `<div class="empty"><strong>No accepted work yet.</strong><span>Browse current opportunities and make your next strong proposal.</span><div style="margin-top:14px"><button class="button primary small" data-view="discover">Find work</button></div></div>`}</section><section class="panel soft"><div class="panel-head"><div><div class="kicker">Inbox</div><h3>Stay in the loop.</h3></div><span class="tag ${unread ? 'urgent' : ''}">${unread} unread</span></div>${notificationList(4)}<button class="text-button" data-view="support">Need help? →</button></section></div></div></section>`; }
function overview() { const completed = state.applications.filter(item => item.status === 'ACCEPTED').length; return `<div class="overview"><div class="overview-item accent"><span>Recorded earnings</span><strong>${money(state.payments.reduce((sum, item) => sum + (item.status === 'COMPLETED' ? Number(item.advance_amount || 0) + Number(item.final_amount || 0) : 0), 0))}</strong></div><div class="overview-item"><span>Jobs completed</span><strong>${state.reviews.length}</strong></div><div class="overview-item"><span>Upcoming jobs</span><strong>${state.schedule.length}</strong></div><div class="overview-item"><span>Applications</span><strong>${state.applications.length + completed}</strong></div></div>`; }
function nextJob(job) { return `<div class="next-job"><span class="tag">${esc(label(job.status))}</span><h3 class="next-job-title">${esc(job.job_title)}</h3><p class="next-job-meta">${esc(job.job_category)} · ${dateLabel(job.scheduled_date)} · ${timeLabel(job.start_time)}–${timeLabel(job.end_time)}</p><p class="next-job-meta">Agreement locked for this schedule. Payment state is shown in Earnings.</p><div class="next-price"><span>Agreed amount</span><strong>See Earnings</strong></div></div>`; }
function notificationList(limit = 15) { const items = state.notifications.slice(0, limit); return items.length ? items.map(item => `<button class="notification ${item.is_read ? '' : 'unread'}" data-action="notification" data-id="${item.id}"><i class="notification-dot"></i><span><strong>${esc(item.title)}</strong><small>${esc(item.message)}</small><em>${dateLabel(item.created_at)}</em></span></button>`).join('') : '<div class="empty"><strong>No notifications yet.</strong><span>Updates about applications, agreements, and payments will appear here.</span></div>'; }

function renderDiscover() { $('#main').innerHTML = `<section class="page"><div class="shell">${pageHeader('Opportunity board', 'Find your next good job.', 'Scan what is open, understand the ask, and make a proposal that works for you.', '<button class="button secondary small" data-action="refresh">Refresh ↻</button>')}<div class="filters"><input id="job-search" placeholder="Search category, place, or title" aria-label="Search jobs"><select id="job-urgency" aria-label="Filter urgency"><option value="">Every urgency</option><option value="RELAXED">Relaxed</option><option value="NEEDED_IN_A_DAY">Needed in a day</option><option value="URGENT">Urgent</option></select><input id="job-min" type="number" min="0" placeholder="Minimum ₹" aria-label="Minimum price"><button class="button secondary small" data-action="clear-filters">Reset</button></div><div class="board"><section class="panel"><div class="panel-head"><div><div class="kicker">Open opportunities</div><h3>Worth a closer look.</h3></div><span class="tag" id="job-count">${state.jobs.length} jobs</span></div><div class="opportunity-list" id="opportunity-list">${opportunityList(state.jobs)}</div></section><aside class="panel soft"><div class="kicker">Fair opportunity</div><h3 style="font:400 27px var(--display);margin:0 0 10px">A clearer market is coming.</h3><p style="color:var(--muted);font-size:12px">AI opportunity insights are not exposed by the current backend. This space is reserved for transparent demand, skill-shortage, and worker-concentration signals when that capability is available.</p><div class="support-note">No fabricated match scores here. Apply based on the real job details, your skills, and your schedule.</div></aside></div></div></section>`; bindFilters(); }
function opportunityList(items) { if (!items.length) return '<div class="empty"><strong>Nothing matching your current view.</strong><span>Try a broader search or reset the filters.</span></div>'; return items.map(job => `<article class="opportunity"><div><h3 class="opportunity-title">${esc(job.title)}</h3><div class="opportunity-meta">${esc(job.category)} · ${esc(job.location)} · ${dateLabel(job.scheduled_date)} ${job.start_time ? `· ${timeLabel(job.start_time)}–${timeLabel(job.end_time)}` : ''}</div><div class="opportunity-facts"><span>${job.required_worker_count} worker${job.required_worker_count === 1 ? '' : 's'}</span><span>${esc(label(job.emergency_level))}</span><span>Reference ${money(job.minimum_platform_cost)}</span></div></div><div class="opportunity-side"><strong>${money(job.minimum_platform_cost)}</strong><button class="button primary small" data-action="open-job" data-id="${job.id}">View job →</button></div></article>`).join(''); }
function bindFilters() { const update = () => { const term = $('#job-search').value.toLowerCase(); const urgency = $('#job-urgency').value; const minimum = Number($('#job-min').value || 0); const items = state.jobs.filter(job => `${job.title} ${job.category} ${job.location}`.toLowerCase().includes(term) && (!urgency || job.emergency_level === urgency) && Number(job.minimum_platform_cost || 0) >= minimum); $('#opportunity-list').innerHTML = opportunityList(items); $('#job-count').textContent = `${items.length} job${items.length === 1 ? '' : 's'}`; }; ['job-search','job-urgency','job-min'].forEach(id => $(`#${id}`).addEventListener('input', update)); $('[data-action="clear-filters"]').addEventListener('click', () => { $('#job-search').value = ''; $('#job-urgency').value = ''; $('#job-min').value = ''; update(); }); }

function renderApplications() { $('#main').innerHTML = `<section class="page"><div class="shell">${pageHeader('Your proposals', 'Applications with a clear status.', 'Keep an eye on what you proposed, what changed, and what needs your response.', '<button class="button primary small" data-view="discover">Find more work</button>')}<div class="panel"><div class="panel-head"><div><div class="kicker">Application ledger</div><h3>${state.applications.length} proposal${state.applications.length === 1 ? '' : 's'}</h3></div></div>${state.applications.length ? state.applications.map(applicationRow).join('') : '<div class="empty"><strong>You haven’t applied to any jobs yet.</strong><span>Open the opportunity board when you are ready to make a proposal.</span></div>'}</div></div></section>`; }
function applicationRow(item) { const last = item.negotiations?.[item.negotiations.length - 1]; return `<div class="application-row"><div><h4>${esc(item.job_title)}</h4><p>${esc(item.job_category)} · ${esc(item.job_location)} · ${dateLabel(item.scheduled_date)} ${item.start_time ? `· ${timeLabel(item.start_time)}–${timeLabel(item.end_time)}` : ''}</p><div class="opportunity-facts"><span>Reference ${money(item.minimum_platform_cost)}</span><span>Your proposal ${money(item.proposed_price)}</span>${last ? `<span>Latest ${money(last.proposed_amount)}</span>` : ''}</div></div><div class="row-side"><span class="tag ${item.status === 'COUNTER_OFFER' ? 'counter' : item.status === 'REJECTED' ? 'urgent' : ''}">${esc(label(item.status))}</span>${['SUBMITTED','COUNTER_OFFER'].includes(item.status) ? `<button class="button secondary small" data-action="counter" data-id="${item.id}">Counter offer</button><button class="button secondary small" data-action="withdraw" data-id="${item.id}">Withdraw</button>` : ''}</div></div>`; }

function renderSchedule() { $('#main').innerHTML = `<section class="page"><div class="shell">${pageHeader('Time is part of the promise', 'Your schedule, without guesswork.', 'Accepted work is time-locked. Availability is what you offer around it.', '<button class="button primary small" data-action="open-availability">+ Add availability</button>')}<div class="board"><section class="panel"><div class="panel-head"><div><div class="kicker">Upcoming work</div><h3>Locked commitments.</h3></div></div>${state.schedule.length ? state.schedule.map(item => `<div class="schedule-row"><div><h4>${esc(item.job_title)}</h4><p>${esc(item.job_category)} · ${dateLabel(item.scheduled_date)} · ${timeLabel(item.start_time)}–${timeLabel(item.end_time)}</p></div><div class="row-side"><span class="tag">${esc(label(item.status))}</span><button class="button primary small" data-action="worker-completion" data-job="${item.job_id}">Task is done</button></div></div>`).join('') : '<div class="empty"><strong>Your next opportunity will appear here once an application is accepted.</strong><span>Keep your availability clear so commitments fit your real day.</span></div>'}</section><section class="panel soft"><div class="panel-head"><div><div class="kicker">Your availability</div><h3>Windows you offer.</h3></div></div>${state.availability.length ? state.availability.map(item => `<div class="schedule-row"><div><h4>${dateLabel(item.available_date)}</h4><p>${timeLabel(item.start_time)}–${timeLabel(item.end_time)} · ${label(item.status)}</p></div><button class="button secondary small" data-action="delete-availability" data-id="${item.id}">Remove</button></div>`).join('') : '<div class="empty"><strong>No availability windows yet.</strong><span>Add a window to make your working rhythm visible.</span></div>'}</section></div></div></section>`; }
function renderEarnings() { const completed = state.payments.filter(item => item.status === 'COMPLETED'); const total = completed.reduce((sum, item) => sum + Number(item.advance_amount || 0) + Number(item.final_amount || 0), 0); $('#main').innerHTML = `<section class="page"><div class="shell">${pageHeader('Money from work', 'Earnings you can explain.', 'Payments are simulated for this hackathon. Every state still stays visible and honest.')}${[['Recorded total', money(total)],['Advance payments', money(completed.reduce((sum, item) => sum + Number(item.advance_amount || 0), 0))],['Final payments', money(completed.reduce((sum, item) => sum + Number(item.final_amount || 0), 0))],['Pending records', state.payments.filter(item => item.status === 'PENDING').length]].map(([key,value], i) => `<div class="overview-item ${i === 0 ? 'accent' : ''}" style="display:inline-block;width:24%;border-bottom:1px solid var(--line);border-right:0"><span>${key}</span><strong>${value}</strong></div>`).join('')}<div class="panel" style="margin-top:20px"><div class="panel-head"><div><div class="kicker">Transactions</div><h3>Recent payment records.</h3></div></div>${state.payments.length ? state.payments.map(item => `<div class="transaction"><div><strong>${esc(label(item.payment_type))} payment</strong><p>${esc(item.transaction_reference || 'Simulated transaction')} · ${dateLabel(item.created_at)}</p></div><div class="row-side"><strong>${money(item.payment_type === 'ADVANCE' ? item.advance_amount : item.final_amount)}</strong><span class="tag ${item.status === 'FAILED' ? 'urgent' : item.status === 'PENDING' ? 'pending' : ''}">${esc(label(item.status))}</span></div></div>`).join('') : '<div class="empty"><strong>No payment records yet.</strong><span>Your earnings history will appear after an agreement is paid.</span></div>'}<p class="support-note" style="margin-top:16px">These are simulated transaction records, not bank, UPI, or cash transfers.</p></div></div></section>`; }
function renderHistory() { const completed = state.applications.filter(item => item.status === 'ACCEPTED'); $('#main').innerHTML = `<section class="page"><div class="shell">${pageHeader('Your work history', 'A record of good work.', 'Completed jobs and reviews become part of your professional story.')}${completed.length ? `<div class="panel">${completed.map(item => `<div class="schedule-row"><div><h4>${esc(item.job_title)}</h4><p>${esc(item.job_category)} · ${esc(item.job_location)} · ${dateLabel(item.scheduled_date)}</p></div><div class="row-side"><strong>${money(item.proposed_price)}</strong><span class="tag">Agreement</span></div></div>`).join('')}</div>` : '<div class="empty"><strong>No completed work history to show yet.</strong><span>Your first accepted opportunity will start the record.</span></div>'}</div></section>`; }
function renderProfile() { const reviews = state.reviews; $('#main').innerHTML = `<section class="page"><div class="shell">${pageHeader('Your working profile', 'Make your reliability legible.', 'Profile editing and worker statistics are limited by the current backend contract.') }<div class="profile-grid"><section class="profile-intro"><span class="tag">Worker account</span><h2>${esc(state.user?.name || 'Worker')}</h2><p>${esc(state.user?.email || 'Email not listed')}</p><div class="profile-stat"><span>Phone</span><strong>${esc(state.user?.phone || 'Not listed')}</strong></div><div class="profile-stat"><span>Reviews received</span><strong>${reviews.length}</strong></div><div class="profile-stat"><span>Account</span><strong>${esc(label(state.user?.account_status))}</strong></div></section><section class="panel"><div class="kicker">Reviews</div><h3 style="font:400 26px var(--display);margin:0 0 12px">What the work says.</h3>${reviews.length ? reviews.map(review => `<div class="review-row"><strong>${'★'.repeat(review.rating)}${'☆'.repeat(5 - review.rating)}</strong><p>${esc(review.comment || 'A rating without a comment.')}</p><small>${dateLabel(review.created_at)}</small></div>`).join('') : '<div class="empty"><strong>No reviews yet.</strong><span>Complete work and invite fair, contextual feedback.</span></div>'}</section></div></div></section>`; }
function renderSupport() { $('#main').innerHTML = `<section class="page"><div class="shell">${pageHeader('Support', 'A clear place to raise an issue.', 'Tell Rozgaar what needs attention. Your report stays attached to the right context.') }<div class="board"><section class="panel"><div class="kicker">Your complaints</div>${state.complaints.length ? state.complaints.map(item => `<div class="schedule-row"><div><h4>${esc(item.category)}</h4><p>${esc(item.message)} · ${dateLabel(item.created_at)}</p></div><span class="tag ${item.status === 'RESOLVED' ? '' : 'pending'}">${esc(label(item.status))}</span></div>`).join('') : '<div class="empty"><strong>No complaints on record.</strong><span>Use the support action from a relevant job when something needs attention.</span></div>'}</section><section class="panel soft"><div class="kicker">Need help with a job?</div><h3 style="font:400 26px var(--display);margin:0 0 10px">Raise a private report.</h3><p style="color:var(--muted);font-size:12px">Choose a job from your applications and describe the issue. The current backend supports job-linked complaints, not a separate safety hotline.</p><button class="button primary small" data-action="complaint" data-job="">Start a complaint</button></section></div></div></section>`; }

function openLoginDrawer() { openDrawer(`<button class="drawer-close" data-action="close-drawer" aria-label="Close">×</button><div class="drawer-head"><p class="eyebrow">Worker access</p><h2>Sign in to find work.</h2><p>Your account opens your applications, schedule, earnings, and notifications.</p></div><form id="login-form"><div class="field"><label for="login-email">Email</label><input id="login-email" type="email" autocomplete="email" required></div><div class="field"><label for="login-password">Password</label><input id="login-password" type="password" autocomplete="current-password" required></div><div class="form-error" id="login-error"></div><button class="button primary" type="submit">Sign in</button></form><p class="drawer-note">New worker? <button class="text-button" type="button" data-action="open-register">Create an account</button></p>`, 'Worker sign in'); $('#login-form').addEventListener('submit', async event => { event.preventDefault(); try { const result = await api('/auth/login', { method: 'POST', body: JSON.stringify({ email: $('#login-email').value, password: $('#login-password').value }) }); state.token = result.access_token; localStorage.setItem('rozgaar_worker_token', state.token); closeDrawer(); await loadCore(); showToast('Welcome to your worker desk.'); } catch (error) { $('#login-error').textContent = error.message; } }); }
function openRegisterDrawer() { openDrawer(`<button class="drawer-close" data-action="close-drawer" aria-label="Close">×</button><div class="drawer-head"><p class="eyebrow">Join Rozgaar</p><h2>Create your worker account.</h2><p>Use the existing Rozgaar account flow. Your role is set to worker by the platform.</p></div><form id="register-form"><div class="field"><label for="register-name">Name</label><input id="register-name" required maxlength="200"></div><div class="field"><label for="register-phone">Phone</label><input id="register-phone" required maxlength="32"></div><div class="field"><label for="register-email">Email</label><input id="register-email" type="email" required autocomplete="email"></div><div class="field"><label for="register-password">Password</label><input id="register-password" type="password" minlength="8" required autocomplete="new-password"></div><div class="form-error" id="register-error"></div><button class="button primary" type="submit">Create worker account</button></form>`, 'Create worker account'); $('#register-form').addEventListener('submit', async event => { event.preventDefault(); try { await api('/auth/register', { method: 'POST', body: JSON.stringify({ name: $('#register-name').value.trim(), phone: $('#register-phone').value.trim(), email: $('#register-email').value.trim(), password: $('#register-password').value, role: 'WORKER' }) }); closeDrawer(); showToast('Account created. Sign in to continue.'); openLoginDrawer(); } catch (error) { $('#register-error').textContent = error.message; } }); }
function openHowItWorks() { openDrawer(`<button class="drawer-close" data-action="close-drawer" aria-label="Close">×</button><div class="drawer-head"><p class="eyebrow">The worker path</p><h2>Find work, with the details in view.</h2><p>Rozgaar keeps the worker’s decision-making clear from opportunity to earnings.</p></div><section class="drawer-section"><div class="section-label">01 · Discover</div><p>Browse real jobs with location, timing, worker count, urgency, and reference price.</p></section><section class="drawer-section"><div class="section-label">02 · Apply</div><p>Choose your proposed price. The current backend keeps the proposal concise and puts negotiation in a separate step.</p></section><section class="drawer-section"><div class="section-label">03 · Schedule</div><p>Once accepted, work becomes a time-locked commitment. Keep other availability windows around it.</p></section><section class="drawer-section"><div class="section-label">04 · Earn</div><p>Payment records distinguish advance, final, pending, and simulated transaction states.</p></section><button class="button primary" data-action="open-login">Sign in to find work</button>`, 'How Rozgaar works'); }
