      openDrawer(`<button class="drawer-close" data-action="close-drawer" aria-label="Close">×</button><div class="drawer-head"><p class="eyebrow">Confirm your working area</p><h2>Set your region before applying.</h2><p>Applications are matched to the area where you currently work. Save a region to continue.</p></div><form id="apply-location-form"><div class="field"><label for="apply-working-location">Working region</label><input id="apply-working-location" placeholder="e.g. New Town, Kolkata" required></div><div class="field"><label for="apply-working-radius">Working radius (km)</label><input id="apply-working-radius" type="number" min="0" max="200" value="25" required></div><div class="form-error" id="apply-location-error"></div><button class="button primary" type="submit">Save region and continue</button></form>`, 'Confirm working area');
