function submitWorkerCompletion(jobId) { openDrawer(`<button class="drawer-close" data-action="close-drawer" aria-label="Close">×</button><div class="drawer-head"><p class="eyebrow">Completion evidence</p><h2>Mark the task as done.</h2><p>Add one clear completion photo before confirming.</p></div><form id="worker-completion-form"><div class="field"><label for="worker-evidence-file">Upload Completion Photo</label><input id="worker-evidence-file" type="file" accept=".jpg,.jpeg,.png,image/jpeg,image/png" required><small>JPG, JPEG, or PNG · maximum 15 MB</small></div><div id="worker-photo-preview"></div><div class="form-error" id="worker-completion-error"></div><button class="button secondary" id="worker-photo-upload" type="button" disabled>Upload Completion Photo</button><button class="button primary" id="worker-completion-submit" type="submit" disabled>Task is done</button></form>`, 'Completion evidence'); const fileInput = $('#worker-evidence-file'); const uploadButton = $('#worker-photo-upload'); const submit = $('#worker-completion-submit'); let selectedFile = null; let uploadedPath = null; fileInput.addEventListener('change', () => { const file = fileInput.files?.[0]; const error = $('#worker-completion-error'); error.textContent = ''; selectedFile = null; uploadedPath = null; uploadButton.disabled = true; submit.disabled = true; if (!file) return; if (!['image/jpeg', 'image/png'].includes(file.type) || !/\.(jpe?g|png)$/i.test(file.name)) { error.textContent = 'Choose a JPG, JPEG, or PNG image.'; fileInput.value = ''; return; } if (file.size > 15 * 1024 * 1024) { error.textContent = 'The completion photo must be 15 MB or smaller.'; fileInput.value = ''; return; } selectedFile = file; uploadButton.disabled = false; $('#worker-photo-preview').innerHTML = `<div class="upload-preview"><img src="${URL.createObjectURL(file)}" alt="Selected completion photo"><span>${esc(file.name)} · ${(file.size / 1024 / 1024).toFixed(2)} MB</span><button type="button" class="text-button" id="worker-photo-remove">Remove/change photo</button></div>`; $('#worker-photo-remove').addEventListener('click', () => { fileInput.value = ''; $('#worker-photo-preview').innerHTML = ''; selectedFile = null; uploadedPath = null; uploadButton.disabled = true; submit.disabled = true; }); }); uploadButton.addEventListener('click', async () => { const error = $('#worker-completion-error'); if (!selectedFile) return; uploadButton.disabled = true; uploadButton.textContent = 'Uploading…'; try { const upload = new FormData(); upload.append('file', selectedFile); const uploadResponse = await api(`/jobs/${jobId}/completion/worker/evidence`, { method: 'POST', body: upload, headers: {} }); uploadedPath = uploadResponse.storage_path; submit.disabled = false; uploadButton.textContent = 'Photo uploaded'; } catch (uploadError) { error.textContent = uploadError.message; uploadButton.disabled = false; uploadButton.textContent = 'Upload Completion Photo'; } }); $('#worker-completion-form').addEventListener('submit', async event => { event.preventDefault(); const error = $('#worker-completion-error'); if (!uploadedPath) { error.textContent = 'Upload a valid completion photo first.'; return; } submit.disabled = true; try { await api(`/jobs/${jobId}/completion/worker`, { method: 'POST', body: JSON.stringify({ storage_bucket: 'completion-evidence', storage_path: uploadedPath }) }); closeDrawer(); showToast('Your completion confirmation was recorded.'); await loadCore(); navigate('schedule'); } catch (completionError) { error.textContent = completionError.message; submit.disabled = false; } }); }
async function deleteAvailability(id) { if (!confirm('Remove this availability window?')) return; try { await api(`/workers/me/availability/${id}`, { method: 'DELETE' }); showToast('Availability removed.'); await loadCore(); navigate('schedule'); } catch (error) { showToast(error.message); } }
async function markNotification(id) {
  const target = state.notifications.find(item => item.id === id);
  if (!target) return;
  const previous = state.notifications.map(item => ({ ...item }));
  state.notifications = state.notifications.map(item => item.id === id ? { ...item, is_read: true } : item);
  renderView();
  try { await api(`/notifications/${id}/read`, { method: 'POST' }); } catch (error) { state.notifications = previous; renderView(); showToast(error.message); }
}
async function markAllRead() {
  if (!state.notifications.some(item => !item.is_read)) return;
  const previous = state.notifications.map(item => ({ ...item }));
  state.notifications = state.notifications.map(item => ({ ...item, is_read: true }));
  renderView();
  try { await api('/notifications/read-all', { method: 'POST' }); } catch (error) { state.notifications = previous; renderView(); showToast(error.message); }
}
