function logout() { state.token = null; state.user = null; localStorage.removeItem('rozgaar_worker_token'); localStorage.removeItem('rozgaar_token'); updateUserArea(); renderLogin(); showToast('You have been signed out.'); }
function showToast(message) { const toast = $('.toast'); if (!toast) return; toast.textContent = message; toast.classList.add('show'); setTimeout(() => toast.classList.remove('show'), 3200); }

const existingRenderDiscover = renderDiscover;
function intelligenceMap(regions, recommendation) {
  if (!regions.length) return '<div class="intelligence-empty">Insufficient regional data for a heatmap.</div>';
  const rows = regions.map(region => `<div class="intelligence-row"><strong>${esc(region.region)}</strong><span>${region.worker_count} workers · ${region.available_worker_count} available · ${region.active_demand} demand</span><em>${esc(region.state)}</em></div>`).join('');
  return `<div id="worker-leaflet-map" class="intelligence-map" aria-label="Regional opportunity geographic map"></div><div class="intelligence-legend"><span><i class="legend-dot shortage"></i>Shortage / underserved</span><span><i class="legend-dot balanced"></i>Balanced</span><span><i class="legend-dot surplus"></i>Oversupplied</span></div><div class="intelligence-rows">${rows}</div>`;
}

function initializeWorkerMap(regions, recommendation) {
  const node = $('#worker-leaflet-map');
  if (!node) return;
  if (!window.L) {
    if (!document.querySelector('link[data-leaflet-css]')) {
      const style = document.createElement('link');
      style.rel = 'stylesheet';
      style.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
      style.dataset.leafletCss = 'true';
      document.head.appendChild(style);
    }
    const script = document.createElement('script');
    script.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
    script.onload = () => initializeWorkerMap(regions, recommendation);
    document.head.appendChild(script);
    return;
  }
  if (workerMap) workerMap.remove();
  workerMap = window.L.map(node, { zoomControl: true, scrollWheelZoom: true });
  window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    maxZoom: 19,
    attribution: '&copy; OpenStreetMap contributors',
  }).addTo(workerMap);
  const normalizedRegions = regions;
  const layers = normalizedRegions.map(region => {
    const ratio = region.supply_demand_ratio ?? (region.active_demand ? region.active_demand / Math.max(region.available_worker_count, 1) : 0);
    const color = recommendation?.region === region.region || region.state === 'SHORTAGE' || region.state === 'UNDERSERVED' ? '#d9684f' : region.state === 'BALANCED' ? '#315c4c' : '#d59b27';
    const layer = window.L.circle([region.latitude, region.longitude], { radius: 0, color, fillColor: color, fillOpacity: 0.22, weight: 2 })
      .bindPopup(`<strong>${esc(region.region)}</strong><br>Workers: ${region.worker_count}<br>Available: ${region.available_worker_count}<br>Demand: ${region.active_demand}<br>Status: ${esc(label(region.state))}`)
      .bindTooltip(esc(region.region), { direction: 'top', sticky: true })
      .addTo(workerMap);
    return layer;
  });
  workerMapLayers = layers;
  const updateMarkerSizes = () => {
    const zoom = workerMap.getZoom();
    const radius = Math.max(220, Math.min(900, 420 * Math.pow(2, zoom - 12)));
    layers.forEach((layer) => layer.setRadius(radius));
  };
  workerMap.on('zoomend', updateMarkerSizes);
  updateMarkerSizes();
  if (normalizedRegions.length) workerMap.fitBounds(window.L.latLngBounds(normalizedRegions.map(region => [region.latitude, region.longitude])).pad(0.25), { maxZoom: 14 });
}

async function normalizeMapRegions(rawRegions) {
  const grouped = new Map();
  rawRegions.filter((region) => region && typeof region === 'object' && Number.isFinite(region.latitude) && Number.isFinite(region.longitude)).forEach((region) => {
    const key = String(region.region || '').trim().toLowerCase().replace(/\s+/g, ' ');
    if (!key) return;
    const current = grouped.get(key) || { ...region, worker_count: 0, available_worker_count: 0, relevant_job_count: 0, active_demand: 0, ongoing_job_count: 0, completed_job_count: 0, coordinateSource: null, records: [] };
    current.records.push(region);
    current.worker_count += Number(region.worker_count || 0);
    current.available_worker_count += Number(region.available_worker_count || 0);
    current.relevant_job_count += Number(region.relevant_job_count || 0);
    current.active_demand += Number(region.active_demand || 0);
    current.ongoing_job_count += Number(region.ongoing_job_count || 0);
    current.completed_job_count += Number(region.completed_job_count || 0);
    if (!current.coordinateSource || Number(region.active_demand || 0) > Number(current.coordinateSource.active_demand || 0) || (Number(region.active_demand || 0) === Number(current.coordinateSource.active_demand || 0) && Number(region.worker_count || 0) > Number(current.coordinateSource.worker_count || 0))) {
      current.latitude = region.latitude;
      current.longitude = region.longitude;
      current.coordinateSource = region;
    }
    grouped.set(key, current);
  });
  return Promise.all([...grouped.values()].map(async (region) => {
    const coordinates = await resolveCanonicalRegionCoordinates(region.region, region.records);
    region.latitude = coordinates[0];
    region.longitude = coordinates[1];
    const ratio = region.available_worker_count ? Number((region.active_demand / region.available_worker_count).toFixed(2)) : null;
    const state = region.active_demand && !region.available_worker_count ? 'UNDERSERVED' : ratio && ratio > 1 ? 'SHORTAGE' : region.available_worker_count && ratio !== null && ratio < 0.5 ? 'OVERSUPPLIED' : 'BALANCED';
    const { records, coordinateSource, ...normalized } = region;
    return { ...normalized, supply_demand_ratio: ratio, state, opportunity_score: Number(Math.min(100, region.active_demand / Math.max(region.available_worker_count, 1) * 50).toFixed(1)) };
  }));
}

async function resolveCanonicalRegionCoordinates(regionName, records) {
  const coordinates = records.map((record) => [Number(record.latitude), Number(record.longitude)]);
  const hasConflictingCoordinates = coordinates.some(([latitude, longitude]) => Math.abs(latitude - coordinates[0][0]) > 0.02 || Math.abs(longitude - coordinates[0][1]) > 0.02);
  if (!hasConflictingCoordinates) return coordinates[0];
  try {
    const response = await fetch(`https://nominatim.openstreetmap.org/search?format=jsonv2&limit=5&q=${encodeURIComponent(`${regionName}, West Bengal`)}`, { headers: { Accept: 'application/json' } });
    const results = await response.json();
    const regionWord = String(regionName).split(',')[0].trim().toLowerCase();
    const match = results.find((item) => item.type !== 'aeroway' && String(item.display_name || '').toLowerCase().includes(regionWord));
    if (match && Number.isFinite(Number(match.lat)) && Number.isFinite(Number(match.lon))) return [Number(match.lat), Number(match.lon)];
  } catch {
    // Keep the real backend coordinate when canonical geocoding is unavailable.
  }
  return coordinates[0];
}
renderDiscover = function () {
  existingRenderDiscover();
  const aside = $('.panel.soft');
  if (!aside) return;
  aside.innerHTML = '<div class="kicker">Fair opportunity</div><h3 style="font:400 27px var(--display);margin:0 0 10px">Regional supply and demand</h3><div id="worker-intelligence">Loading real regional data…</div>';
  api('/location-intelligence/worker').then(async (data) => {
    const node = $('#worker-intelligence');
    if (!node) return;
    if (!data.location.resolved) { node.innerHTML = '<div class="support-note">Set a working location in your profile to see area opportunity.</div>'; return; }
    const regions = await normalizeMapRegions(data.regions);
    const recommendation = regions.find((region) => region.state === 'SHORTAGE' || region.state === 'UNDERSERVED');
    node.innerHTML = `<p style="color:var(--muted);font-size:12px">${regions.length} real regions within your working radius.</p>${intelligenceMap(regions, recommendation)}${recommendation ? `<div class="support-note">Higher opportunity nearby: ${esc(recommendation.region)} · ${esc(recommendation.state.toLowerCase())} · ${recommendation.active_demand} demand / ${recommendation.available_worker_count} available.</div>` : '<div class="support-note">No higher-opportunity nearby region is supported by current data.</div>'}`;
    initializeWorkerMap(regions, recommendation);
  }).catch((error) => { const node = $('#worker-intelligence'); if (node) node.textContent = error.message; });
};
const existingRenderProfile = renderProfile;
renderProfile = function () {
  existingRenderProfile();
  const profile = $('.profile-intro');
  if (!profile) return;
  profile.insertAdjacentHTML('beforeend', '<div class="profile-stat"><span>Working area</span><strong id="working-location-label">Not set</strong></div><form id="location-form" style="margin-top:16px"><div class="field"><label for="working-location">Location</label><input id="working-location" placeholder="e.g. New Town, Kolkata" required></div><div class="field"><label for="working-radius">Radius (km)</label><input id="working-radius" type="number" min="0" max="200" value="25" required></div><div class="form-error" id="location-error"></div><button class="button primary small" type="submit">Save working area</button></form>');
  api('/location-intelligence/worker').then((data) => { $('#working-location').value = data.location.location || ''; $('#working-radius').value = data.working_radius_km ?? 25; $('#working-location-label').textContent = data.location.resolved ? data.location.location : 'Not resolved'; }).catch(() => {});
  $('#location-form').addEventListener('submit', async (event) => { event.preventDefault(); try { await api('/location-intelligence/worker/location', { method: 'PATCH', body: JSON.stringify({ location: $('#working-location').value.trim(), working_radius_km: Number($('#working-radius').value) }) }); showToast('Working area updated.'); await loadCore(); navigate('discover'); } catch (error) { $('#location-error').textContent = error.message; } });
};
function openWorkerReviewForm(jobId, reviewedUserId, reviewedName) { openDrawer(`<button class="drawer-close" data-action="close-drawer" aria-label="Close">×</button><div class="drawer-head"><p class="eyebrow">Completed work</p><h2>Rate ${esc(reviewedName || 'the Consumer')}.</h2><p>Share a fair rating for this completed job.</p></div><form id="worker-review-form"><div class="field"><label for="worker-review-rating">Rating</label><select id="worker-review-rating" required><option value="">Choose 1–5</option><option value="1">1 · Needs improvement</option><option value="2">2 · Fair</option><option value="3">3 · Good</option><option value="4">4 · Very good</option><option value="5">5 · Excellent</option></select></div><div class="field"><label for="worker-review-comment">Comment (optional)</label><textarea id="worker-review-comment" maxlength="2000"></textarea></div><div class="form-error" id="worker-review-error"></div><button class="button primary" type="submit">Submit rating</button></form>`, 'Submit rating'); $('#worker-review-form').addEventListener('submit', async event => { event.preventDefault(); try { await api(`/jobs/${jobId}/reviews`, { method: 'POST', body: JSON.stringify({ reviewed_user_id: reviewedUserId, rating: Number($('#worker-review-rating').value), comment: $('#worker-review-comment').value.trim() || null }) }); closeDrawer(); showToast('Rating recorded.'); await loadCore(); navigate('history'); } catch (error) { $('#worker-review-error').textContent = error.message; } }); }
document.addEventListener('click', event => { const trigger = event.target.closest('[data-action="worker-review"]'); if (trigger) openWorkerReviewForm(trigger.dataset.job, trigger.dataset.user, trigger.dataset.name); });
const existingWorkerOpenJob = openJob;
openJob = async function (id) { await existingWorkerOpenJob(id); const job = state.jobs.find(item => item.id === id); if (!job || !job.consumer_name) return; const detail = $('.drawer-section:last-of-type'); if (detail) detail.insertAdjacentHTML('afterbegin', `<div class="support-note">Consumer: ${esc(job.consumer_name)} · ${job.consumer_rating ? `★ ${Number(job.consumer_rating).toFixed(1)} (${job.consumer_review_count} reviews)` : 'No reviews yet'}</div>`); };
opportunityList = function (items) { if (!items.length) return '<div class="empty"><strong>Nothing matching your current view.</strong><span>Try a broader search or reset your filters.</span></div>'; return items.map(job => `<article class="opportunity"><div><h3 class="opportunity-title">${esc(job.title)}</h3><div class="opportunity-meta">${esc(job.category)} · ${esc(job.location)} · ${dateLabel(job.scheduled_date)} ${job.start_time ? `· ${timeLabel(job.start_time)}–${timeLabel(job.end_time)}` : ''}</div><div class="opportunity-facts"><span>${job.required_worker_count} worker${job.required_worker_count === 1 ? '' : 's'}</span><span>${esc(label(job.emergency_level))}</span><span>Reference ${money(job.minimum_platform_cost)}</span></div>${job.consumer_name ? `<div class="support-note">Consumer: ${esc(job.consumer_name)} · ${job.consumer_rating ? `★ ${Number(job.consumer_rating).toFixed(1)} (${job.consumer_review_count} reviews)` : 'No reviews yet'}</div>` : ''}</div><div class="opportunity-side"><strong>${money(job.minimum_platform_cost)}</strong><button class="button primary small" data-action="open-job" data-id="${job.id}">View job →</button></div></article>`).join(''); };
const existingWorkerRenderHistory = renderHistory;
renderHistory = function () { existingWorkerRenderHistory(); $$('.schedule-row').forEach(row => { const title = $('h4', row)?.textContent; const application = state.applications.find(item => item.job_title === title && item.status === 'ACCEPTED'); const job = application ? state.jobs.find(item => item.id === application.job_id) : null; if (!job?.consumer_id) return; const review = state.reviews.find(item => item.job_id === job.id && item.reviewed_user_id === job.consumer_id); const side = $('.row-side', row); if (side) side.insertAdjacentHTML('beforeend', review ? `<small>You gave ${review.rating}/5 to ${esc(job.consumer_name || 'the Consumer')}</small>` : `<button class="button secondary small" data-action="worker-review" data-job="${job.id}" data-user="${job.consumer_id}" data-name="${esc(job.consumer_name || 'the Consumer')}">Rate Consumer</button>`); }); };
document.addEventListener('click', event => { if (event.target.closest('[data-action="logout"]')) window.RozgaarRealtime?.stop(); });
